export { RadioGroup as Radio, RadioGroupItem as RadioItem } from '@/components/ui/radio-group'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
/**
 * Presents a labeled single-choice group with per-option disabled states and controlled value updates.
 */
export function RadioButtons({
  options,
  value,
  onValueChange,
  disabled,
  label,
}: {
  options: { value: string; label: React.ReactNode; disabled?: boolean }[]
  value?: string
  onValueChange?: (value: string) => void
  disabled?: boolean
  label?: string
}) {
  return (
    <RadioGroup
      aria-label={label}
      value={value}
      onValueChange={onValueChange}
      disabled={disabled}
      className="inline-flex gap-0 overflow-hidden rounded-lg border"
    >
      {options.map((option) => (
        <label
          key={option.value}
          className={`relative cursor-pointer border-r px-4 py-2 text-sm last:border-0 ${value === option.value ? 'bg-primary/10 text-primary' : ''}`}
        >
          <RadioGroupItem
            value={option.value}
            disabled={option.disabled}
            className="absolute inset-0 h-full w-full rounded-none border-0 opacity-0"
          />
          {option.label}
        </label>
      ))}
    </RadioGroup>
  )
}

'use client'

import * as React from 'react'
import { cn } from '@/lib/utils'
import { CircleIcon } from 'lucide-react'
import { RadioGroup as RadioGroupPrimitive } from 'radix-ui'

function RadioGroup({
  className,
  ...props
}: React.ComponentProps<typeof RadioGroupPrimitive.Root>) {
  return (
    <RadioGroupPrimitive.Root
      data-slot="radio-group"
      className={cn('grid gap-3', className)}
      {...props}
    />
  )
}

function RadioGroupItem({
  className,
  ...props
}: React.ComponentProps<typeof RadioGroupPrimitive.Item>) {
  return (
    <RadioGroupPrimitive.Item
      data-slot="radio-group-item"
      className={cn(
        'aspect-square size-4 shrink-0 rounded-full border border-input text-primary shadow-xs transition-[color,box-shadow] outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:bg-input/30 dark:aria-invalid:ring-destructive/40',
        className,
      )}
      {...props}
    >
      <RadioGroupPrimitive.Indicator
        data-slot="radio-group-indicator"
        className="relative flex items-center justify-center"
      >
        <CircleIcon className="absolute top-1/2 left-1/2 size-2 -translate-x-1/2 -translate-y-1/2 fill-primary" />
      </RadioGroupPrimitive.Indicator>
    </RadioGroupPrimitive.Item>
  )
}

export { RadioGroup, RadioGroupItem }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
